dashboard.definition:
{
 "title": "Firewall Details",
 "description": "One Palo Alto firewall: sessions, dataplane health, HA, sensors, versions and licences (PAN-OS XML API over gNMI), throughput and errors per interface, and drop counters",
 "inputs": {
  "input_site": {
   "type": "input.dropdown",
   "title": "Site",
   "dataSources": {
    "primary": "ds_sites"
   },
   "options": {
    "token": "site",
    "defaultValue": "ibk-lab",
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\")"
   }
  },
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-4h@m,now"
   }
  },
  "input_fw": {
   "type": "input.dropdown",
   "title": "Firewall",
   "dataSources": {
    "primary": "ds_fws"
   },
   "options": {
    "token": "tk_fw",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"node\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"node\") | renameSeries(\"value\")"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "90s",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_ha_role": {
   "type": "splunk.singlevalue",
   "title": "HA role (this unit)",
   "dataSources": {
    "primary": "ds_ha_role"
   },
   "options": {
    "majorColor": "#708794"
   }
  },
  "viz_active": {
   "type": "splunk.singlevalue",
   "title": "Active sessions",
   "dataSources": {
    "primary": "ds_active"
   },
   "options": {
    "majorColor": "#708794"
   }
  },
  "viz_util": {
   "type": "splunk.singlevalue",
   "title": "Session table used",
   "dataSources": {
    "primary": "ds_util"
   },
   "options": {
    "majorColor": "#708794",
    "unit": "%",
    "unitPosition": "after",
    "colorMode": "block",
    "rangeValues": [
     80,
     90
    ],
    "rangeColors": [
     "#65A637",
     "#F8BE34",
     "#D93F3C"
    ]
   }
  },
  "viz_cps": {
   "type": "splunk.singlevalue",
   "title": "Connections/s",
   "dataSources": {
    "primary": "ds_cps_now"
   },
   "options": {
    "majorColor": "#708794"
   }
  },
  "viz_cpu": {
   "type": "splunk.singlevalue",
   "title": "Dataplane CPU",
   "dataSources": {
    "primary": "ds_cpu_now"
   },
   "options": {
    "majorColor": "#708794",
    "unit": "%",
    "unitPosition": "after",
    "colorMode": "block",
    "rangeValues": [
     70,
     90
    ],
    "rangeColors": [
     "#65A637",
     "#F8BE34",
     "#D93F3C"
    ]
   }
  },
  "viz_health": {
   "type": "splunk.singlevalue",
   "title": "Health issues",
   "dataSources": {
    "primary": "ds_health"
   },
   "options": {
    "majorColor": "#708794",
    "colorMode": "block",
    "rangeValues": [
     1
    ],
    "rangeColors": [
     "#65A637",
     "#D93F3C"
    ]
   }
  },
  "viz_in_total": {
   "type": "splunk.singlevalue",
   "title": "Total in (5 min average)",
   "dataSources": {
    "primary": "ds_in_total"
   },
   "options": {
    "majorColor": "#708794",
    "unit": "Mb/s",
    "unitPosition": "after"
   }
  },
  "viz_out_total": {
   "type": "splunk.singlevalue",
   "title": "Total out (5 min average)",
   "dataSources": {
    "primary": "ds_out_total"
   },
   "options": {
    "majorColor": "#708794",
    "unit": "Mb/s",
    "unitPosition": "after"
   }
  },
  "viz_err_ifs": {
   "type": "splunk.singlevalue",
   "title": "Interfaces with errors",
   "dataSources": {
    "primary": "ds_err_ifs"
   },
   "options": {
    "majorColor": "#708794"
   }
  },
  "viz_in": {
   "type": "splunk.line",
   "title": "In by interface, Mb/s (5 min average)",
   "dataSources": {
    "primary": "ds_in"
   },
   "options": {
    "legendDisplay": "bottom"
   },
   "showProgressBar": true
  },
  "viz_out": {
   "type": "splunk.line",
   "title": "Out by interface, Mb/s (5 min average)",
   "dataSources": {
    "primary": "ds_out"
   },
   "options": {
    "legendDisplay": "bottom"
   },
   "showProgressBar": true
  },
  "viz_sessions": {
   "type": "splunk.line",
   "title": "Active sessions",
   "dataSources": {
    "primary": "ds_active"
   },
   "options": {
    "legendDisplay": "off",
    "nullValueDisplay": "gaps"
   },
   "showProgressBar": true
  },
  "viz_errs": {
   "type": "splunk.column",
   "title": "Errors per 5 min by interface (in + out)",
   "dataSources": {
    "primary": "ds_errs"
   },
   "options": {
    "stackMode": "stacked",
    "legendDisplay": "bottom"
   },
   "showProgressBar": true,
   "containerOptions": {
    "visibility": {
     "hideWhenNoData": true
    }
   }
  },
  "viz_proto": {
   "type": "splunk.line",
   "title": "Active sessions by protocol",
   "dataSources": {
    "primary": "ds_proto"
   },
   "options": {
    "legendDisplay": "bottom",
    "nullValueDisplay": "gaps"
   },
   "showProgressBar": true
  },
  "viz_new_sess": {
   "type": "splunk.column",
   "title": "New sessions per 5 min",
   "dataSources": {
    "primary": "ds_new_sess"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_cps_chart": {
   "type": "splunk.line",
   "title": "Connections per second",
   "dataSources": {
    "primary": "ds_cps"
   },
   "options": {
    "legendDisplay": "off",
    "nullValueDisplay": "gaps"
   },
   "showProgressBar": true
  },
  "viz_kbps": {
   "type": "splunk.line",
   "title": "Throughput (kbps) and packets per second",
   "dataSources": {
    "primary": "ds_kbps"
   },
   "options": {
    "legendDisplay": "bottom",
    "nullValueDisplay": "gaps"
   },
   "showProgressBar": true
  },
  "viz_table": {
   "type": "splunk.table",
   "title": "Interfaces, whole time range",
   "dataSources": {
    "primary": "ds_table"
   },
   "options": {
    "count": 30
   },
   "showProgressBar": true
  },
  "viz_cpu_chart": {
   "type": "splunk.line",
   "title": "Dataplane CPU %, average and max over cores (minute window)",
   "dataSources": {
    "primary": "ds_cpu"
   },
   "options": {
    "legendDisplay": "bottom",
    "nullValueDisplay": "gaps"
   },
   "showProgressBar": true
  },
  "viz_dp_pb": {
   "type": "splunk.line",
   "title": "Packet buffer and descriptor %",
   "dataSources": {
    "primary": "ds_dp_pb"
   },
   "options": {
    "legendDisplay": "bottom",
    "nullValueDisplay": "gaps"
   },
   "showProgressBar": true
  },
  "viz_dp_sess": {
   "type": "splunk.line",
   "title": "Session table % (dataplane)",
   "dataSources": {
    "primary": "ds_dp_sess"
   },
   "options": {
    "legendDisplay": "bottom",
    "nullValueDisplay": "gaps"
   },
   "showProgressBar": true
  },
  "viz_ha_table": {
   "type": "splunk.table",
   "title": "HA: local vs peer",
   "dataSources": {
    "primary": "ds_ha_table"
   },
   "options": {
    "count": 20
   },
   "showProgressBar": true
  },
  "viz_ha_sync": {
   "type": "splunk.table",
   "title": "HA sync and compatibility (only mismatches are listed)",
   "dataSources": {
    "primary": "ds_ha_sync"
   },
   "options": {
    "count": 20
   },
   "showProgressBar": true
  },
  "viz_alarms": {
   "type": "splunk.singlevalue",
   "title": "Sensors in alarm",
   "dataSources": {
    "primary": "ds_alarms"
   },
   "options": {
    "majorColor": "#708794",
    "colorMode": "block",
    "rangeValues": [
     1
    ],
    "rangeColors": [
     "#65A637",
     "#D93F3C"
    ]
   }
  },
  "viz_psu": {
   "type": "splunk.table",
   "title": "Power supplies",
   "dataSources": {
    "primary": "ds_psu"
   },
   "options": {
    "count": 10
   },
   "showProgressBar": true
  },
  "viz_temps": {
   "type": "splunk.table",
   "title": "Temperatures (C)",
   "dataSources": {
    "primary": "ds_temps"
   },
   "options": {
    "count": 20
   },
   "showProgressBar": true
  },
  "viz_fans": {
   "type": "splunk.table",
   "title": "Fans (rpm)",
   "dataSources": {
    "primary": "ds_fans"
   },
   "options": {
    "count": 20
   },
   "showProgressBar": true
  },
  "viz_versions": {
   "type": "splunk.table",
   "title": "Versions and uptime",
   "dataSources": {
    "primary": "ds_versions"
   },
   "options": {
    "count": 20
   },
   "showProgressBar": true
  },
  "viz_sigs": {
   "type": "splunk.table",
   "title": "Signature ages (warn: threat, app, av over 7 days; WildFire over 1 day)",
   "dataSources": {
    "primary": "ds_sigs"
   },
   "options": {
    "count": 10
   },
   "showProgressBar": true
  },
  "viz_lic": {
   "type": "splunk.table",
   "title": "Licences (days left; expired when below 0)",
   "dataSources": {
    "primary": "ds_lic"
   },
   "options": {
    "count": 30
   },
   "showProgressBar": true
  },
  "viz_drop_chart": {
   "type": "splunk.column",
   "title": "Top 10 drop and error counters, change per 5 min",
   "dataSources": {
    "primary": "ds_drop_chart"
   },
   "options": {
    "stackMode": "stacked",
    "legendDisplay": "bottom"
   },
   "showProgressBar": true
  },
  "viz_drop_table": {
   "type": "splunk.table",
   "title": "Drop and error counters, whole time range (total since boot)",
   "dataSources": {
    "primary": "ds_drop_table"
   },
   "options": {
    "count": 100
   },
   "showProgressBar": true
  }
 },
 "dataSources": {
  "ds_sites": {
   "type": "ds.search",
   "name": "sites",
   "options": {
    "query": "| mcatalog values(site) as site WHERE `mdt_metrics_index` | mvexpand site | rename site as label | eval value=label"
   }
  },
  "ds_fws": {
   "type": "ds.search",
   "name": "fws",
   "options": {
    "query": "| mstats count(_value) WHERE `mdt_metrics_index` site=\"$site$\" metric_name=mdt_panos_* BY extracted_source | rename extracted_source as node | fields node | sort node"
   }
  },
  "ds_flow": {
   "type": "ds.search",
   "name": "flow",
   "options": {
    "query": "| mstats latest(mdt_panos_if_stats_in_octets) as in_octets latest(mdt_panos_if_stats_out_octets) as out_octets latest(mdt_panos_if_stats_in_errors) as in_errors latest(mdt_panos_if_stats_out_errors) as out_errors WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" span=1m BY extracted_source interface_name | eval node=extracted_source, interface=interface_name | fields - extracted_source interface_name | `mdt_if_rates` | bin _time span=5m | stats avg(in_bps) as in_bps avg(out_bps) as out_bps sum(in_errs) as in_errs sum(out_errs) as out_errs by _time interface | where _time + 300 <= now()"
   }
  },
  "ds_sessions": {
   "type": "ds.search",
   "name": "sessions",
   "options": {
    "query": "| mstats latest(mdt_panos_xml_session_num_active) as active latest(mdt_panos_xml_session_num_max) as max WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" span=5m"
   }
  },
  "ds_sess_proto": {
   "type": "ds.search",
   "name": "sess_proto",
   "options": {
    "query": "| mstats latest(mdt_panos_xml_session_num_tcp) as tcp latest(mdt_panos_xml_session_num_udp) as udp latest(mdt_panos_xml_session_num_icmp) as icmp WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" span=5m"
   }
  },
  "ds_sess_rate": {
   "type": "ds.search",
   "name": "sess_rate",
   "options": {
    "query": "| mstats latest(mdt_panos_xml_session_cps) as cps latest(mdt_panos_xml_session_kbps) as kbps latest(mdt_panos_xml_session_pps) as pps WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" span=5m"
   }
  },
  "ds_installed": {
   "type": "ds.search",
   "name": "installed",
   "options": {
    "query": "| mstats latest(mdt_panos_xml_session_num_installed) as inst WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" span=5m"
   }
  },
  "ds_dp": {
   "type": "ds.search",
   "name": "dp",
   "options": {
    "query": "| mstats latest(mdt_panos_xml_dp_cpu_avg) as cpu_avg latest(mdt_panos_xml_dp_cpu_max) as cpu_max WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" span=5m"
   }
  },
  "ds_dp_res": {
   "type": "ds.search",
   "name": "dp_res",
   "options": {
    "query": "| mstats latest(mdt_panos_xml_dp_session_avg) as session_avg latest(mdt_panos_xml_dp_session_max) as session_max latest(mdt_panos_xml_dp_packet_buffer_avg) as packet_buffer_avg latest(mdt_panos_xml_dp_packet_buffer_max) as packet_buffer_max latest(mdt_panos_xml_dp_packet_descriptor_avg) as packet_descriptor_avg latest(mdt_panos_xml_dp_packet_descriptor_max) as packet_descriptor_max WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" span=5m"
   }
  },
  "ds_drops": {
   "type": "ds.search",
   "name": "drops",
   "options": {
    "query": "| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_counters_value span=5m BY counter"
   }
  },
  "ds_drop_table": {
   "type": "ds.search",
   "name": "drop_table",
   "options": {
    "query": "| mstats earliest(_value) as first latest(_value) as total WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_counters_value BY counter desc | eval change=total-first | sort 0 -change | rename counter as Counter, desc as Description, change as \"Change in range\", total as \"Total since boot\" | table Counter Description \"Change in range\" \"Total since boot\""
   }
  },
  "ds_ha_role": {
   "type": "ds.search",
   "name": "ha_role",
   "options": {
    "query": "| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_state span=1m BY unit state | sort 0 -_time | dedup unit | where unit=\"local\" | eval \"HA role\"=state | fields \"HA role\""
   }
  },
  "ds_alarms": {
   "type": "ds.search",
   "name": "alarms",
   "options": {
    "query": "| mstats latest(_value) as alarms WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_env_alarms earliest=-15m | rename alarms as \"Sensors in alarm\" | fields \"Sensors in alarm\""
   }
  },
  "ds_temps": {
   "type": "ds.search",
   "name": "temps",
   "options": {
    "query": "| mstats latest(_value) as Reading WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_env_temp_c earliest=-15m BY sensor | rename sensor as Sensor | sort Sensor | table Sensor Reading"
   }
  },
  "ds_fans": {
   "type": "ds.search",
   "name": "fans",
   "options": {
    "query": "| mstats latest(_value) as RPM WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_env_rpm earliest=-15m BY sensor | rename sensor as Fan | sort Fan | table Fan RPM"
   }
  },
  "ds_psu": {
   "type": "ds.search",
   "name": "psu",
   "options": {
    "query": "| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_env_status earliest=-15m BY sensor status | rename sensor as \"Power supply\" | table \"Power supply\" status"
   }
  },
  "ds_lic": {
   "type": "ds.search",
   "name": "lic",
   "options": {
    "query": "| mstats latest(_value) as exp WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_license_expires earliest=-2d BY feature | eval Expires=strftime(exp, \"%Y-%m-%d\"), days_left=round((exp - now()) / 86400, 0) | sort days_left | rename feature as Feature, days_left as \"Days left\" | table Feature Expires \"Days left\""
   }
  },
  "ds_ha_table": {
   "type": "ds.search",
   "name": "ha_table",
   "options": {
    "query": "| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_state span=1m BY unit state | sort 0 -_time | dedup unit | eval Item=\"State\", val=state | fields unit Item val | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_priority earliest=-6m BY unit | eval Item=\"Priority\" | fields unit Item val] | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_state_duration earliest=-6m BY unit | eval Item=\"Time in state (s)\" | fields unit Item val] | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_serial span=1m BY unit serial | sort 0 -_time | dedup unit | eval Item=\"Serial\", val=serial | fields unit Item val] | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_build_rel span=1m BY unit build_rel | sort 0 -_time | dedup unit | eval Item=\"Build\", val=build_rel | fields unit Item val] | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_ha1_status span=1m BY unit ha1_status | sort 0 -_time | dedup unit | eval Item=\"Link ha1\", val=ha1_status | fields unit Item val] | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_ha1_backup_status span=1m BY unit ha1_backup_status | sort 0 -_time | dedup unit | eval Item=\"Link ha1-backup\", val=ha1_backup_status | fields unit Item val] | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_ha2_status span=1m BY unit ha2_status | sort 0 -_time | dedup unit | eval Item=\"Link ha2\", val=ha2_status | fields unit Item val] | append [| mstats latest(_value) as val WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_conn_status span=1m BY unit conn_status | sort 0 -_time | dedup unit | eval Item=\"Peer connection\", val=conn_status | fields unit Item val] | chart values(val) as val over Item by unit | eval ord=case(Item=\"State\", 1, Item=\"Priority\", 2, Item=\"Time in state (s)\", 3, Item=\"Serial\", 4, Item=\"Build\", 5, Item=\"Link ha1\", 6, Item=\"Link ha1-backup\", 7, Item=\"Link ha2\", 8, Item=\"Peer connection\", 9) | sort 0 ord | fields - ord | rename local as Local, peer as Peer | table Item Local Peer"
   }
  },
  "ds_ha_sync": {
   "type": "ds.search",
   "name": "ha_sync",
   "options": {
    "query": "| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_mode span=1m BY mode | sort 0 -_time | head 1 | eval Item=\"Mode\", Value=mode | fields Item Value | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_running_sync span=1m BY running_sync | sort 0 -_time | head 1 | eval Item=\"Running sync\", Value=running_sync | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_state_sync span=1m BY state_sync | sort 0 -_time | head 1 | eval Item=\"State sync\", Value=state_sync | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_vpnclient_compat earliest=-6m BY vpnclient_compat | eval Item=\"VPN client compat\", Value=vpnclient_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_app_compat earliest=-6m BY app_compat | eval Item=\"App compat\", Value=app_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_threat_compat earliest=-6m BY threat_compat | eval Item=\"Threat compat\", Value=threat_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_av_compat earliest=-6m BY av_compat | eval Item=\"Antivirus compat\", Value=av_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_url_compat earliest=-6m BY url_compat | eval Item=\"URL filtering compat\", Value=url_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_gpclient_compat earliest=-6m BY gpclient_compat | eval Item=\"GlobalProtect client compat\", Value=gpclient_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_build_compat earliest=-6m BY build_compat | eval Item=\"Build compat\", Value=build_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_iot_compat earliest=-6m BY iot_compat | eval Item=\"IoT compat\", Value=iot_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_dlp_compat earliest=-6m BY dlp_compat | eval Item=\"DLP compat\", Value=dlp_compat | fields Item Value] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_oc_compat earliest=-6m BY oc_compat | eval Item=\"OpenConfig compat\", Value=oc_compat | fields Item Value] | table Item Value"
   }
  },
  "ds_versions": {
   "type": "ds.search",
   "name": "versions",
   "options": {
    "query": "| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_sw_version earliest=-2d BY sw_version | sort 0 -_time | head 1 | eval Item=\"Software\", Version=sw_version | fields Item Version | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_app_version earliest=-2d BY app_version | sort 0 -_time | head 1 | eval Item=\"App\", Version=app_version | fields Item Version] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_threat_version earliest=-2d BY threat_version | sort 0 -_time | head 1 | eval Item=\"Threat\", Version=threat_version | fields Item Version] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_av_version earliest=-2d BY av_version | sort 0 -_time | head 1 | eval Item=\"Antivirus\", Version=av_version | fields Item Version] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_wildfire_version earliest=-2d BY wildfire_version | sort 0 -_time | head 1 | eval Item=\"WildFire\", Version=wildfire_version | fields Item Version] | append [| mstats latest(_value) as v WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_url_version earliest=-2d BY url_version | sort 0 -_time | head 1 | eval Item=\"URL filtering\", Version=url_version | fields Item Version] | append [| mstats latest(_value) as up WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_uptime earliest=-2d | eval Item=\"Uptime (days)\", Version=round(up / 86400, 1) | fields Item Version] | table Item Version"
   }
  },
  "ds_sigs": {
   "type": "ds.search",
   "name": "sigs",
   "options": {
    "query": "| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_app_release earliest=-2d | eval Signature=\"App\", Released=strftime(rel, \"%Y-%m-%d %H:%M\"), age=round((now() - rel) / 86400, 1) | fields Signature Released age | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_threat_release earliest=-2d | eval Signature=\"Threat\", Released=strftime(rel, \"%Y-%m-%d %H:%M\"), age=round((now() - rel) / 86400, 1) | fields Signature Released age] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_av_release earliest=-2d | eval Signature=\"Antivirus\", Released=strftime(rel, \"%Y-%m-%d %H:%M\"), age=round((now() - rel) / 86400, 1) | fields Signature Released age] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_url_release earliest=-2d | eval Signature=\"URL filtering\", Released=strftime(rel, \"%Y-%m-%d %H:%M\"), age=round((now() - rel) / 86400, 1) | fields Signature Released age] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_wildfire_release earliest=-2d | eval Signature=\"WildFire\", Released=strftime(rel, \"%Y-%m-%d %H:%M\"), age=round((now() - rel) / 86400, 1) | fields Signature Released age] | rename age as \"Age (days)\" | table Signature Released \"Age (days)\""
   }
  },
  "ds_health": {
   "type": "ds.search",
   "name": "health",
   "options": {
    "query": "| makeresults | eval grp=\"seed\", n=0 | fields grp n | append [| mstats count(_value) as n WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_*_compat earliest=-6m | eval n=if(n > 0, 1, 0), grp=\"HA\" | fields grp n] | append [| mstats count(_value) as n WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_running_sync running_sync!=\"synchronized\" earliest=-6m | eval n=if(n > 0, 1, 0), grp=\"HA\" | fields grp n] | append [| mstats count(_value) as n WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_ha1_status ha1_status!=\"up\" earliest=-6m | eval n=if(n > 0, 1, 0), grp=\"HA\" | fields grp n] | append [| mstats count(_value) as n WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_ha1_backup_status ha1_backup_status!=\"up\" earliest=-6m | eval n=if(n > 0, 1, 0), grp=\"HA\" | fields grp n] | append [| mstats count(_value) as n WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_ha2_status ha2_status!=\"up\" earliest=-6m | eval n=if(n > 0, 1, 0), grp=\"HA\" | fields grp n] | append [| mstats count(_value) as n WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_ha_conn_status conn_status!=\"up\" earliest=-6m | eval n=if(n > 0, 1, 0), grp=\"HA\" | fields grp n] | append [| mstats latest(_value) as n WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_env_alarms earliest=-15m | where n > 0 | stats count as n | eval grp=\"Alarms\"] | append [| mstats latest(_value) as exp WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_license_expires earliest=-2d BY feature | where exp < now() + 30 * 86400 | stats count as n | eval grp=\"Licences\"] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_app_release earliest=-2d | where rel < now() - 604800 | stats count as n | eval grp=\"Signatures\"] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_threat_release earliest=-2d | where rel < now() - 604800 | stats count as n | eval grp=\"Signatures\"] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_av_release earliest=-2d | where rel < now() - 604800 | stats count as n | eval grp=\"Signatures\"] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_url_release earliest=-2d | where rel < now() - 604800 | stats count as n | eval grp=\"Signatures\"] | append [| mstats latest(_value) as rel WHERE `mdt_metrics_index` extracted_source=\"$tk_fw$\" metric_name=mdt_panos_xml_system_wildfire_release earliest=-2d | where rel < now() - 86400 | stats count as n | eval grp=\"Signatures\"] | stats max(n) as n by grp | stats sum(n) as \"Health issues\""
   }
  },
  "ds_active": {
   "type": "ds.chain",
   "name": "active",
   "options": {
    "extend": "ds_sessions",
    "query": "| timechart span=5m max(active) as \"Active sessions\""
   }
  },
  "ds_util": {
   "type": "ds.chain",
   "name": "util",
   "options": {
    "extend": "ds_sessions",
    "query": "| eval \"Session table %\"=round(active / max * 100, 2) | fields _time \"Session table %\""
   }
  },
  "ds_proto": {
   "type": "ds.chain",
   "name": "proto",
   "options": {
    "extend": "ds_sess_proto",
    "query": "| timechart span=5m max(tcp) as TCP max(udp) as UDP max(icmp) as ICMP"
   }
  },
  "ds_cps": {
   "type": "ds.chain",
   "name": "cps",
   "options": {
    "extend": "ds_sess_rate",
    "query": "| timechart span=5m max(cps) as \"Connections/s\""
   }
  },
  "ds_kbps": {
   "type": "ds.chain",
   "name": "kbps",
   "options": {
    "extend": "ds_sess_rate",
    "query": "| timechart span=5m max(kbps) as \"kbps\" max(pps) as \"pps\""
   }
  },
  "ds_new_sess": {
   "type": "ds.chain",
   "name": "new_sess",
   "options": {
    "extend": "ds_installed",
    "query": "| sort 0 _time | delta inst as d | where d >= 0 | eval \"New sessions per 5 min\"=d | fields _time \"New sessions per 5 min\""
   }
  },
  "ds_cps_now": {
   "type": "ds.chain",
   "name": "cps_now",
   "options": {
    "extend": "ds_sess_rate",
    "query": "| sort 0 _time | tail 1 | eval \"Connections/s\"=cps | fields \"Connections/s\""
   }
  },
  "ds_cpu_now": {
   "type": "ds.chain",
   "name": "cpu_now",
   "options": {
    "extend": "ds_dp",
    "query": "| sort 0 _time | tail 1 | eval \"Dataplane CPU %\"=round(cpu_avg, 1) | fields \"Dataplane CPU %\""
   }
  },
  "ds_cpu": {
   "type": "ds.chain",
   "name": "cpu",
   "options": {
    "extend": "ds_dp",
    "query": "| timechart span=5m max(cpu_avg) as \"CPU avg %\" max(cpu_max) as \"CPU max %\""
   }
  },
  "ds_dp_pb": {
   "type": "ds.chain",
   "name": "dp_pb",
   "options": {
    "extend": "ds_dp_res",
    "query": "| timechart span=5m max(packet_buffer_avg) as \"Packet buffer avg %\" max(packet_buffer_max) as \"Packet buffer max %\" max(packet_descriptor_avg) as \"Descriptor avg %\" max(packet_descriptor_max) as \"Descriptor max %\""
   }
  },
  "ds_dp_sess": {
   "type": "ds.chain",
   "name": "dp_sess",
   "options": {
    "extend": "ds_dp_res",
    "query": "| timechart span=5m max(session_avg) as \"Session avg %\" max(session_max) as \"Session max %\""
   }
  },
  "ds_drop_chart": {
   "type": "ds.chain",
   "name": "drop_chart",
   "options": {
    "extend": "ds_drops",
    "query": "| sort 0 counter _time | streamstats current=f window=1 last(v) as prev by counter | eval change=v - prev | where change >= 0 | timechart span=5m sum(change) by counter limit=10 useother=f"
   }
  },
  "ds_in_total": {
   "type": "ds.chain",
   "name": "in_total",
   "options": {
    "extend": "ds_flow",
    "query": "| stats sum(in_bps) as v by _time | eval \"In (Mb/s)\"=round(v / 1000000, 1) | fields _time \"In (Mb/s)\""
   }
  },
  "ds_out_total": {
   "type": "ds.chain",
   "name": "out_total",
   "options": {
    "extend": "ds_flow",
    "query": "| stats sum(out_bps) as v by _time | eval \"Out (Mb/s)\"=round(v / 1000000, 1) | fields _time \"Out (Mb/s)\""
   }
  },
  "ds_err_ifs": {
   "type": "ds.chain",
   "name": "err_ifs",
   "options": {
    "extend": "ds_flow",
    "query": "| stats sum(in_errs) as i sum(out_errs) as o by interface | where coalesce(i, 0) + coalesce(o, 0) > 0 | stats count as \"Interfaces with errors\""
   }
  },
  "ds_in": {
   "type": "ds.chain",
   "name": "in",
   "options": {
    "extend": "ds_flow",
    "query": "| eval v=round(in_bps / 1000000, 2) | eventstats max(v) as m by interface | where m > 0 | xyseries _time interface v | fillnull value=0"
   }
  },
  "ds_out": {
   "type": "ds.chain",
   "name": "out",
   "options": {
    "extend": "ds_flow",
    "query": "| eval v=round(out_bps / 1000000, 2) | eventstats max(v) as m by interface | where m > 0 | xyseries _time interface v | fillnull value=0"
   }
  },
  "ds_errs": {
   "type": "ds.chain",
   "name": "errs",
   "options": {
    "extend": "ds_flow",
    "query": "| eval v=coalesce(in_errs, 0) + coalesce(out_errs, 0) | eventstats max(v) as m by interface | where m > 0 | xyseries _time interface v | fillnull value=0"
   }
  },
  "ds_table": {
   "type": "ds.chain",
   "name": "table",
   "options": {
    "extend": "ds_flow",
    "query": "| eventstats max(_time) as last | eval in_now=if(_time == last, in_bps, null()), out_now=if(_time == last, out_bps, null()) | stats max(in_now) as in_now max(out_now) as out_now avg(in_bps) as in_avg avg(out_bps) as out_avg max(in_bps) as in_max max(out_bps) as out_max sum(in_errs) as in_errs sum(out_errs) as out_errs by interface | foreach in_* out_* [eval <<FIELD>>=if(match(\"<<FIELD>>\", \"errs$\"), <<FIELD>>, round(<<FIELD>> / 1000000, 2))] | join type=left interface [| mstats latest(_value) WHERE `mdt_metrics_index` metric_name=mdt_panos_if_info_negotiated_port_speed extracted_source=\"$tk_fw$\" earliest=-15m BY interface_name negotiated_port_speed | append [| mstats latest(_value) WHERE `mdt_metrics_index` metric_name=mdt_panos_if_info_negotiated_duplex_mode extracted_source=\"$tk_fw$\" earliest=-15m BY interface_name negotiated_duplex_mode] | append [| mstats latest(_value) as a WHERE `mdt_metrics_index` metric_name=mdt_panos_if_info_auto_negotiate extracted_source=\"$tk_fw$\" earliest=-15m BY interface_name | eval auto=if(a==1, \"yes\", \"no\")] | append [| mstats latest(_value) as mtu WHERE `mdt_metrics_index` metric_name=mdt_panos_if_info_mtu extracted_source=\"$tk_fw$\" earliest=-15m BY interface_name] | stats values(negotiated_port_speed) as speed values(negotiated_duplex_mode) as duplex values(auto) as auto max(mtu) as mtu by interface_name | eval speed=replace(replace(speed, \"^.*SPEED_(.*?)B?$\", \"\\1\"), \"UNKNOWN\", \"unknown\"), duplex=if(match(lower(duplex), \"^(full|half)$\"), lower(duplex), null()) | rename interface_name as interface] | sort 0 - in_max | rename interface as Interface, speed as Speed, duplex as Duplex, auto as \"Auto-neg\", mtu as MTU, in_now as \"In now (Mb/s)\", out_now as \"Out now (Mb/s)\", in_avg as \"In avg (Mb/s)\", out_avg as \"Out avg (Mb/s)\", in_max as \"In peak (Mb/s)\", out_max as \"Out peak (Mb/s)\", in_errs as \"Errors in\", out_errs as \"Errors out\" | table Interface Speed Duplex \"Auto-neg\" MTU \"In now (Mb/s)\" \"Out now (Mb/s)\" \"In avg (Mb/s)\" \"Out avg (Mb/s)\" \"In peak (Mb/s)\" \"Out peak (Mb/s)\" \"Errors in\" \"Errors out\""
   }
  }
 },
